@js:
   let fpic = `[oncontextmenu="return false"]@src`,
   bpic = String(java.getString(fpic)).replace(/\d{3}\.jpg$/,''),
   pages = java.getString('.pages.-2@text'),
   list = [];
   for (let i = 1; i <= pages; i++) {
      list.push('<br><img src="' + bpic + String(i).padStart(3, '0') + '.jpg">'); 
   }
   list.join('');

